INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch05$PT145-S2-Q3$batch05$, 145, 2, 3, $batch05$Necessary Assumption$batch05$, $batch05$The current sharp decline in commercial honeybee populations has been attributed to the same viral and bacterial infections, pesticide poisonings, and mite infestations that devastated bees in the past. Whichever of these adverse conditions is the immediate cause, it is highly likely that there is also a long-ignored underlying condition, and that is inbreeding. Decades of breeding practices meant to maximize pollinating efficiency have limited honeybees’ genetic diversity.$batch05$, $batch05$Which one of the following is an assumption that is required by the argument?$batch05$, $batch05$E$batch05$, true, $batch05$Batch 05; question text from local bank.$batch05$ FROM lr_sections s WHERE s.preptest=145 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT145-S2-Q3$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$A$batch05$, $batch05$Commercial honeybees are more vulnerable to problems with inbreeding than wild honeybees are.$batch05$, $batch05$Irrelevant Comparison$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT145-S2-Q3$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$A$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$B$batch05$, $batch05$The results of decades of breeding practices cannot be quickly undone.$batch05$, $batch05$Not Necessary$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT145-S2-Q3$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$B$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$C$batch05$, $batch05$The genetic diversity of the honeybee population continues to decline.$batch05$, $batch05$Not Necessary$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT145-S2-Q3$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$C$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$D$batch05$, $batch05$In the past, viral infections and mites have devastated genetically diverse honeybee populations.$batch05$, $batch05$Weakens$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT145-S2-Q3$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$D$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$E$batch05$, $batch05$Lack of genetic diversity can make honeybees more vulnerable to adverse conditions.$batch05$, $batch05$Correct$batch05$, true FROM lr_questions q WHERE q.qid=$batch05$PT145-S2-Q3$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$E$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT145-S2-Q3$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$Inbreeding is likely an underlying cause of the current decline in commercial honeybees.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$Decades of breeding for pollinating efficiency have limited honeybees' genetic diversity.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$The evidence shows low genetic diversity. The conclusion says that low diversity is helping kill the bees. Nothing connects the two. The author also says the immediate causes are the familiar ones: infections, poisons, mites. So the link has to be that low diversity makes bees more vulnerable to exactly those things.$batch05$), (3, $batch05$Goal$batch05$, $batch05$A link: low genetic diversity makes honeybees more vulnerable to these threats.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT145-S2-Q3$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$Wild bees never come up. The argument is about commercial bees.$batch05$), ($batch05$B$batch05$, $batch05$Whether the damage can be undone quickly is a question about the fix, not the cause.$batch05$), ($batch05$C$batch05$, $batch05$Diversity does not need to keep falling. Being low is enough for the argument.$batch05$), ($batch05$D$batch05$, $batch05$If threats wiped out genetically diverse populations in the past, diversity does not protect bees. That cuts against the idea that low diversity is the hidden problem.$batch05$), ($batch05$E$batch05$, $batch05$Negate it: "lack of genetic diversity *cannot* make honeybees more vulnerable to adverse conditions." Then inbreeding does nothing to help the infections and mites along, and it is no underlying cause at all.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT145-S2-Q3$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
